      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string' },
          limit: { type: 'integer', minimum: 1, maximum: 4, default: 2 }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'search_records') {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32602;
    throw err;
