  if (!Number.isInteger(limit) || limit < 1 || limit > 4) {
    const err = new Error('limit must be an integer between 1 and 4');
    err.code = -32602;
    throw err;
  }

  // Check for extra arguments
  const knownKeys = new Set(['query', 'limit']);
